'use strict';
const fs=require('fs'),path=require('path');const{chromium}=require('playwright');
const BASE='https://plan-ex.ru/erpv2/',U=p=>new URL(p,BASE).href,OUT=path.resolve(process.env.P15_OUT||'P15_cleanup_restore_output'),SHOTS=path.join(OUT,'P15_screenshots');fs.mkdirSync(SHOTS,{recursive:true});const COMPANY=27,DUP=26,OWNER='p14_owner_260804221827',TEMP='P15 DELETE TEMP рейс';
function creds(){const e=process.env.P15_CREDENTIALS_B64||'';return e?JSON.parse(Buffer.from(e,'base64').toString('utf8')):[]}function sa(){return creds().find(x=>String(x?.role||'').toUpperCase()==='SUPERADMIN')}
async function login(b,u,pw){const c=await b.newContext({viewport:{width:1920,height:1080},deviceScaleFactor:1,locale:'ru-RU',timezoneId:'Europe/Moscow'}),p=await c.newPage();let ok=false;try{await p.goto(U('login'),{waitUntil:'domcontentloaded'});await p.locator('input[name="username"],input[name="email"],input[type="text"]').first().fill(u);await p.locator('input[type="password"]').fill(pw);await Promise.all([p.waitForLoadState('domcontentloaded').catch(()=>{}),p.locator('button[type="submit"],input[type="submit"]').first().click()]);await p.waitForTimeout(400);ok=!/\/login(?:[/?#]|$)/.test(p.url())}catch{}return{c,p,ok}}
function candidates(t,v){const a=[...v];for(const m of String(t).matchAll(/[A-Za-z0-9!@#$%^&*()_+\-=]{8,64}/g))a.push(m[0]);return[...new Set(a)].filter(x=>x!==OWNER&&!x.includes('@example.test')&&!/^[a-f0-9]{64}$/i.test(x))}
async function owner(b){const s=sa(),x=await login(b,s.username,s.password);await x.p.goto(U(`superadmin/companies/${COMPANY}/users`),{waitUntil:'domcontentloaded'});const f=x.p.locator(`form[action$="/superadmin/companies/${COMPANY}/owner/reset-password"]`).first(),n=x.p.waitForNavigation({waitUntil:'domcontentloaded'});await f.evaluate(z=>HTMLFormElement.prototype.submit.call(z));await n;const vals=await x.p.locator('input,textarea,code,pre,[data-password]').evaluateAll(ns=>ns.map(y=>y.value||y.textContent||'').filter(Boolean)),list=candidates(await x.p.locator('body').innerText(),vals);await x.c.close();for(const q of list){const y=await login(b,OWNER,q);if(y.ok)return y;await y.c.close()}throw Error('owner login failed')}
(async()=>{const r={status:'FAIL',route:{deletedRecordFound:false,restoreFormFound:false,restored:false,relationsVisible:false},duplicateTenant:{archived:false,workingTenantActive:false},consoleErrors:[],pageErrors:[],requestFailures:[],httpFailures:[],error:null};let b;try{b=await chromium.launch({headless:true});const s=sa(),a=await login(b,s.username,s.password);if(!a.ok)throw Error('superadmin login failed');const p=a.p;p.on('console',m=>{if(m.type()==='error')r.consoleErrors.push(m.text())});p.on('pageerror',e=>r.pageErrors.push(String(e.message||e)));p.on('requestfailed',q=>r.requestFailures.push(q.url()));p.on('response',z=>{if(z.status()>=500)r.httpFailures.push({status:z.status(),url:z.url()})});await p.goto(U('superadmin/deleted-data'),{waitUntil:'domcontentloaded'});let row=p.locator('tr,.card,.panel').filter({hasText:TEMP}).first();if(!(await row.count()))row=p.locator('tr,.card,.panel').filter({hasText:/linear_route|Рейс/i}).filter({hasText:'4'}).first();r.route.deletedRecordFound=(await row.count())>0;if(await row.count()){const restore=row.locator('form').filter({hasText:/Восстановить/i}).first();r.route.restoreFormFound=(await restore.count())>0;if(await restore.count()){const nav=p.waitForNavigation({waitUntil:'domcontentloaded'}).catch(()=>null);await restore.evaluate(z=>HTMLFormElement.prototype.submit.call(z));await nav;await p.waitForTimeout(500)}}await p.goto(U(`superadmin/companies/${DUP}`),{waitUntil:'domcontentloaded'});r.duplicateTenant.archived=/Архив|archived/i.test(await p.locator('body').innerText());await p.goto(U(`superadmin/companies/${COMPANY}`),{waitUntil:'domcontentloaded'});r.duplicateTenant.workingTenantActive=/Актив|active/i.test(await p.locator('body').innerText());await p.screenshot({path:path.join(SHOTS,'P15_013_SUPERADMIN_restore_and_tenant_status_1920x1080.png'),fullPage:false});await a.c.close();const o=await owner(b);await o.p.goto(U('company/trips/linear'),{waitUntil:'networkidle'});const restored=o.p.locator('tr[data-linear-route-id]').filter({hasText:TEMP}).first();r.route.restored=(await restored.count())>0;if(r.route.restored){await restored.dblclick();await o.p.waitForTimeout(500);const text=await o.p.locator('#linear-trip-view-modal').innerText().catch(()=>'');r.route.relationsVisible=text.includes('P14 Клиент ООО Тест')&&text.includes('П14 Перевозчик ООО Тест')&&text.includes('П14 Водитель Тестовый')}await o.p.screenshot({path:path.join(SHOTS,'P15_014_OWNER_restored_trip_1920x1080.png'),fullPage:false});await o.c.close();r.status=r.route.deletedRecordFound&&r.route.restoreFormFound&&r.route.restored&&r.route.relationsVisible&&r.duplicateTenant.archived&&r.duplicateTenant.workingTenantActive&&r.pageErrors.length===0&&r.requestFailures.length===0&&r.httpFailures.length===0?'PASS':'FAIL'}catch(e){r.error={name:e.name||'Error',message:String(e.message||e).slice(0,800)}}finally{if(b)await b.close().catch(()=>{});fs.writeFileSync(path.join(OUT,'P15_CLEANUP_RESTORE_RUNTIME.json'),JSON.stringify(r,null,2));console.log('P15_CLEANUP_RESTORE='+r.status);process.exitCode=r.status==='PASS'?0:1}})();
